formulas.expression:
OR(
    ISBLANK({!screen_email1.value}),
    AND(
        /* exactly one "@" */
        (LEN({!screen_email1.value}) - LEN(SUBSTITUTE({!screen_email1.value}, "@", ""))) = 1,

        /* "@" is not the first character */
        FIND("@", {!screen_email1.value}) > 1,

        /* no spaces */
        NOT(CONTAINS({!screen_email1.value}, " ")),

        /* the part AFTER the "@" contains a "." */
        CONTAINS(
            MID({!screen_email1.value},
                FIND("@", {!screen_email1.value}) + 1,
                LEN({!screen_email1.value})),
            "."
        ),

        /* the character right after "@" is not "." (blocks "@.") */
        NOT(MID({!screen_email1.value}, FIND("@", {!screen_email1.value}) + 1, 1) = "."),

        /* does not end in "." */
        NOT(RIGHT({!screen_email1.value}, 1) = ".")
    )
)
